from taf.internal.sw.neat.client.neat_admin.v1.configuration import Configuration
from taf.sw.neat.httpclient.ApiClientLocal import ApiClientLocal
from taf.sw.neat.httpclient.neat_uri import NameSpacesURI, InventoryURI

class InventoryManagerV1(object):
    def __init__(self, conn_details, configuration, access_token):
        self.conn_details = conn_details
        self.configuration = Configuration()
        self.configuration.verify_ssl = False
        self.configuration.host = conn_details.make_configuration_host(original_endpoint=self.configuration.get_host_from_settings(index=None))
        self.api_client = ApiClientLocal(configuration, access_token)

    def get_container_registry_secrets(self, timeout=60):
        return self.api_client.send_get_request(uri=InventoryURI.container_registries_uri, timeout=timeout)['data']

    def get_container_registry_secret_by_id(self, registry_id, timeout=60):
        return self.api_client.send_get_request(uri=InventoryURI.container_registries_uri + "/" +
                                                registry_id, timeout=timeout)['data']

    def update_container_registry_secret(self, registry_id, timeout=60, **kwargs):
        body = {"data": {
                    "type": "container-registry",
                    "id": registry_id,
                    "attributes": kwargs
                }
            }
        headers = {"Content-Type": "application/merge-patch+json"}
        return self.api_client.send_patch_request(uri=InventoryURI.container_registries_uri + "/" +
                                                registry_id, json=body, headers=headers, timeout=timeout)['data']

    def create_container_registry_secret(self, timeout=60, **kwargs):
        body = {"data": {
                    "type": "container-registry",
                    "attributes": kwargs
                }
            }
        headers = {"Content-Type": "application/json"}
        return self.api_client.send_post_request(uri=InventoryURI.container_registries_uri,
                                                json=body, headers=headers, timeout=timeout)['data']

    def delete_container_registry_secret(self, registry_id, timeout=60):
        return self.api_client.send_delete_request(uri=InventoryURI.container_registries_uri + "/" +
                                                   registry_id, timeout=timeout)

    def get_container_registry_namespaces(self, timeout=60):
        return self.api_client.send_get_request(uri=NameSpacesURI.namespace_uri, timeout=timeout)['data']

    def create_container_registry_namespace(self, credential_id, registry_id, timeout=60, **kwargs):
        body = {"data": {
                    "type": "container-registry-namespace",
                    "attributes": kwargs,
                    "relationships": {
                        "credentials": {
                            "data": {
                                "type": "container-registry-credentials",
                                "id": credential_id
                            }
                        },
                        "registry": {
                            "data": {
                                "type": "container-registry",
                                "id": registry_id
                            }
                        }
                    }
                }
            }
        headers = {"Content-Type": "application/json"}
        return self.api_client.send_post_request(uri=NameSpacesURI.namespace_uri, json=body,
                                                 headers=headers, timeout=timeout)['data']

    def get_container_registry_namespace_by_id(self, namespace_id, timeout=60):
        return self.api_client.send_get_request(uri=NameSpacesURI.namespace_uri + "/" +
                                                namespace_id, timeout=timeout)['data']

    def delete_container_registry_namespace(self, namespace_id, timeout=60):
        return self.api_client.send_delete_request(uri=NameSpacesURI.namespace_uri + "/" +
                                                    namespace_id, timeout=timeout)
